-- PT112-S1-Q5. Batch 09.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch09$PT112-S1-Q5$batch09$ AND q.stimulus=$batch09$Company policy: An employee of our company must be impartial, particularly when dealing with family members. This obligation extends to all aspects of the job, including hiring and firing practices and the quality of service the employee provides customers.$batch09$ AND q.prompt=$batch09$Which one of the following employee behaviors most clearly violates the company policy cited above?$batch09$ AND q.correct_choice=$batch09$A$batch09$) THEN RAISE EXCEPTION 'Question changed: PT112-S1-Q5'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch09$PT112-S1-Q5$batch09$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT112-S1-Q5'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch09$PT112-S1-Q5$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch09$Rule$batch09$, $batch09$Employees must be impartial, especially with family members. This covers everything about the job, including hiring and firing and the quality of service to customers.$batch09$), (1, $batch09$Evaluate$batch09$, $batch09$Impartial means family status makes no difference, either way. Treating relatives worse is as partial as treating them better. To prove a violation, a choice has to show family status driving the decision. A choice where family might simply deserve the outcome doesn't prove anything.$batch09$), (2, $batch09$Goal$batch09$, $batch09$A decision that clearly turns on someone being family, against the merits.$batch09$)) v(position,label,body) WHERE q.qid=$batch09$PT112-S1-Q5$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch09$A$batch09$, $batch09$All five siblings are more qualified than every other applicant, and still none are hired. The only thing that explains the decision is that they're family. That's partial, just in the unexpected direction.$batch09$), ($batch09$B$batch09$, $batch09$Everyone who complained gets the same gift, the employee's mother included. Family gets no special treatment.$batch09$), ($batch09$C$batch09$, $batch09$This is a trap, picked by 7%. Never firing three siblings sounds suspicious. But maybe none of them ever deserved firing. Without knowing they performed badly, we can't call this partial.$batch09$), ($batch09$D$batch09$, $batch09$This might be unfair, since the problems are over two years old. But the policy targets partiality, and nothing ties this employee to any family relationship. The problems also did happen, so the claims aren't false.$batch09$), ($batch09$E$batch09$, $batch09$This is the most-picked trap, at 10%. Promoting a relative over someone else is only partial if the relative wasn't the better choice. E gives no comparison. The relative may well have earned it. A, by contrast, tells us the relatives were the better choice.$batch09$)) v(letter,body) WHERE q.qid=$batch09$PT112-S1-Q5$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
